internal sealed class WageRulesForm:SessionForm
{
    protected override bool ShowNavigationTools=>false;
    private readonly Guid project;private readonly DataGridView policies=AccrualFoundationForm.Grid(),claims=AccrualFoundationForm.Grid();private readonly ListPager policyPager,claimPager;
    private readonly Button create=Button("Yeni kural…"),revise=Button("Seçili kuralın yeni sürümü…"),approvePolicy=Button("Kuralı bağımsız onayla…"),rejectPolicy=Button("Kuralı reddet…"),cancelPolicy=Button("Taslak kuralı iptal et…"),prepare=Button("Onaylı kuraldan talep…"),details=Button("Talep hesap / işlem geçmişi…"),approve=Button("Talebi bağımsız onayla…"),reject=Button("Talebi reddet…"),cancel=Button("Aktarılmamış talebi iptal et…"),post=Button("Onaylı talebi deftere aktar…"),requestReverse=Button("Tam ters aktarım iste…"),approveReverse=Button("Ters aktarımı bağımsız onayla…"),reverse=Button("Onaylı tam ters aktarımı yap…");
