    private static Button Button(string text)=>new(){Text=text,AutoSize=true};
    internal static DataRow? Row(DataGridView g)=>g.SelectedRows.Count==1&&g.SelectedRows[0].DataBoundItem is DataRowView v?v.Row:null;
    private static FlowLayoutPanel Bar(params Control[] controls){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new(8)};bar.Controls.AddRange(controls);return bar;}
    internal WageRulesForm(Guid project,UserSession user)
    {
        this.project=project;Session=user;PersistGridLayout=false;Text="Muhasebe — Ek ücret / gider kuralları";ClientSize=new(1280,850);var tabs=new TabControl{Dock=DockStyle.Fill};var p=new TabPage("Tarihli ve onaylı kural sürümleri");p.Controls.Add(policies);p.Controls.Add(Bar(create,revise,approvePolicy,rejectPolicy,cancelPolicy,prepare));var c=new TabPage("Talep / bağımsız onay / aktarım geçmişi");c.Controls.Add(claims);c.Controls.Add(Bar(details,approve,reject,cancel,post,requestReverse,approveReverse,reverse));tabs.TabPages.AddRange([p,c]);Controls.Add(tabs);policyPager=ListPager.Attach(policies,this,ReloadPoliciesAsync,"kural sürümü");claimPager=ListPager.Attach(claims,this,ReloadClaimsAsync,"talep");
        var refresh=Button("Güncel kural ve talepleri yenile");var close=Button("Kapat");Controls.Add(Bar(refresh,close));note.Text="TRY · Günlük/aylık temel, ek fazla mesai farkı, ek ödeme veya doğrudan proje gideri. Mevzuat katsayısı ve hak birimi varsayılmaz. Hazırlama/onay bakiye değiştirmez; bağımsız onaylı aktarım ayrı yapılır. Aynı çalışma dönemi temel ücreti saatlik/günlük/aylık olarak çoğaltılamaz. Banka transferi yapılmaz.";Controls.Add(note);SizeChanged+=(_,_)=>note.MaximumSize=new(Math.Max(1,ClientSize.Width-24),0);
        WagePresentation.Format(policies);WagePresentation.Format(claims);policies.SelectionChanged+=(_,_)=>RefreshEditState();claims.SelectionChanged+=(_,_)=>RefreshEditState();
        create.Click+=async(_,_)=>await PolicyDialogAsync(null);revise.Click+=async(_,_)=>{if(Row(policies) is{} row)await PolicyDialogAsync(row);};approvePolicy.Click+=async(_,_)=>await DecidePolicyAsync("Approve");rejectPolicy.Click+=async(_,_)=>await DecidePolicyAsync("Reject");cancelPolicy.Click+=async(_,_)=>await DecidePolicyAsync("Cancel");
        prepare.Click+=async(_,_)=>{if(Row(policies) is not{} row||row.Field<string?>("DecisionKind")!="Approve")return;DataTable? targets=null;if(!await RunOperationAsync(async ct=>targets=await Service.TargetsAsync(project,ct))||IsDisposed||targets==null)return;using var d=new WageClaimDialog(project,User,row,targets);Watch(d);d.ShowDialog(this);if(!IsDisposed){await ReloadAsync();tabs.SelectedTab=c;}};
        details.Click+=async(_,_)=>{if(Row(claims) is not{} row)return;Wire.WageClaimView? view=null;if(!await RunOperationAsync(async ct=>view=await Service.ReadAsync(new(project,row.Field<Guid>("ClaimId")),ct))||IsDisposed||view==null)return;using var d=new WageClaimDetailsForm(User,view);Watch(d);d.ShowDialog(this);};
        approve.Click+=async(_,_)=>await ActAsync("Approve");reject.Click+=async(_,_)=>await ActAsync("Reject");cancel.Click+=async(_,_)=>await ActAsync("Cancel");requestReverse.Click+=async(_,_)=>await ActAsync("RequestReverse");approveReverse.Click+=async(_,_)=>await ActAsync("ApproveReverse");post.Click+=async(_,_)=>await TransferAsync("Post");reverse.Click+=async(_,_)=>await TransferAsync("Reverse");refresh.Click+=async(_,_)=>await ReloadAsync();close.Click+=(_,_)=>Close();RefreshAction=ReloadAsync;Load+=async(_,_)=>await ReloadAsync();SessionRevoked+=(_,_)=>Close();PageRequested+=(_,_)=>Close();
    }
    protected override void OnLoad(EventArgs e){base.OnLoad(e);MinimumSize=LogicalToDeviceUnits(new Size(850,650));}
    private void Watch(SessionForm d)=>d.SessionRevoked+=(_,_)=>NotifySessionRevoked();
    private async Task PolicyDialogAsync(DataRow? previous){using var d=new WagePolicyDialog(project,User,previous);Watch(d);d.ShowDialog(this);if(!IsDisposed)await ReloadPoliciesAsync();}
    private async Task DecidePolicyAsync(string kind){if(Row(policies) is not{} row)return;var request=new Wire.WagePolicyDecision(project,row.Field<Guid>("PolicyId"),Guid.NewGuid(),((byte[])row["RecordVersion"]).ToArray(),kind,"");using var d=new WageDecisionDialog(User,"Kural sürümü — "+WagePresentation.Value(kind),request,$"{row["RuleCode"]} · Sürüm {row["Revision"]} · {row["Name"]}\nTür: {WagePresentation.Value(row["Kind"].ToString()!)}\nTarihler: {row["ValidFrom"]} – {row["ValidTo"]}\nBirim TL: {row["UnitAmount"]} · Ek katsayı: {row["PremiumFactor"]} · Bölen: {row["Divisor"]}\nHazırlayan: {row["CreatedBy"]}\nYeni onaylı sürüm geçerli olduğu aralıkta eski sürüme göre hazırlanmış henüz aktarılmamış talepleri geçersiz kılabilir. Önceki aktarılmış kayıtlar değişmez.");Watch(d);d.ShowDialog(this);if(!IsDisposed)await ReloadPoliciesAsync();}
    private async Task ActAsync(string kind){if(Row(claims) is not{} row)return;var request=new Wire.WageClaimAction(project,row.Field<Guid>("ClaimId"),Guid.NewGuid(),((byte[])row["RecordVersion"]).ToArray(),kind,"");using var d=new WageDecisionDialog(User,"Ücret/gider talebi — "+WagePresentation.Value(kind),request,$"Talep: {row["ClaimId"]}\nKaynak belge: {row["DocumentKey"]}\nKişi: {row["PersonCaption"]}\nTutar: {row["Amount"]} TL · Tür: {WagePresentation.Value(row["Kind"].ToString()!)}\nHazırlayan: {row["CreatedBy"]}\n\nOnay/istek para veya bakiye hareketi oluşturmaz. İptal/ret yalnız aktarılmamış talebi sonuçlandırır. Tam ters aktarım isteği ve bağımsız onayı ayrı adımlardır; banka iadesi yapılmaz.");Watch(d);d.ShowDialog(this);if(!IsDisposed)await ReloadClaimsAsync();}
    private async Task TransferAsync(string kind){if(Row(claims) is not{} row)return;Guid claim=row.Field<Guid>("ClaimId");string caption=row["DocumentKey"]+" · "+row["PersonCaption"];Wire.AccrualPostingQuote? quote=null;if(!await RunOperationAsync(async ct=>quote=await Service.TransferQuoteAsync(new(project,claim,kind),ct))||IsDisposed||quote==null)return;using var d=new WageTransferDialog(project,claim,kind,User,caption,quote);Watch(d);d.ShowDialog(this);if(!IsDisposed)await ReloadClaimsAsync();}
    private async Task PageAsync(string section,DataGridView grid,ListPager pager)=>await RunOperationAsync(async ct=>{grid.ClearSelection();var p=await Service.BrowseAsync(new(project,section,pager.Index,pager.SizeLimit),ct);if(IsDisposed)return;var data=RemoteApi.Decode(p.Data);grid.DataSource=data;grid.ClearSelection();pager.Apply(new(data,p.Total,p.Index,p.Size));});
    private Task ReloadPoliciesAsync()=>PageAsync("Policies",policies,policyPager);private Task ReloadClaimsAsync()=>PageAsync("Claims",claims,claimPager);private async Task ReloadAsync(){await ReloadPoliciesAsync();if(!IsDisposed)await ReloadClaimsAsync();}
    protected override void RefreshEditState()
    {
        bool admin=!IsOperationRunning&&Session?.Role==UserRole.Admin;var p=Row(policies);var c=Row(claims);string state=c?["WorkflowState"].ToString()??"";bool pending=p!=null&&p.IsNull("DecisionKind");create.Enabled=admin;revise.Enabled=admin&&p!=null&&!pending;approvePolicy.Enabled=rejectPolicy.Enabled=admin&&pending&&p!.Field<bool>("CanDecide");cancelPolicy.Enabled=admin&&pending;prepare.Enabled=admin&&p?.Field<string?>("DecisionKind")=="Approve";details.Enabled=!IsOperationRunning&&c!=null;approve.Enabled=reject.Enabled=admin&&state=="Prepared";cancel.Enabled=admin&&state is "Prepared" or "Approved";post.Enabled=admin&&state=="Approved";requestReverse.Enabled=admin&&state=="Posted";approveReverse.Enabled=admin&&state=="ReverseRequested";reverse.Enabled=admin&&state=="ReverseApproved";policyPager?.UpdateState();claimPager?.UpdateState();
    }
}

internal sealed class WagePolicyDialog:CalendarEditDialog
{
    private readonly Guid project,id=Guid.NewGuid();private readonly Guid? previous;
    private readonly TextBox code=new(){Width=420,MaxLength=30},name=new(){Width=420,MaxLength=100};private readonly ComboBox kind=new(){Width=420,DropDownStyle=ComboBoxStyle.DropDownList};
    private readonly DateTimePicker from=new(){Width=200,Format=DateTimePickerFormat.Short},to=new(){Width=200,Format=DateTimePickerFormat.Short,ShowCheckBox=true,Checked=false};
    private readonly NumericUpDown unit=new(){Width=220,DecimalPlaces=2,Minimum=0,Maximum=1000000,ThousandsSeparator=true},factor=new(){Width=220,DecimalPlaces=4,Minimum=0,Maximum=5},divisor=new(){Width=220,Minimum=0,Maximum=60};
    internal WagePolicyDialog(Guid project,UserSession user,DataRow? prior):base(user,"Muhasebe — Tarihli ücret/gider kural sürümü","Ücret/gider kuralı")
    {
        this.project=project;ClientSize=new(800,850);previous=prior?.Field<Guid>("PolicyId");foreach(string k in WageRuleService.Kinds)kind.Items.Add(WagePresentation.Value(k));kind.SelectedIndexChanged+=(_,_)=>Configure();kind.SelectedIndex=0;
        if(prior!=null){code.Text=prior["RuleCode"].ToString();name.Text=prior["Name"].ToString();kind.SelectedIndex=Array.IndexOf(WageRuleService.Kinds,prior.Field<string>("Kind")!);unit.Value=prior.Field<decimal>("UnitAmount");factor.Value=prior.Field<decimal>("PremiumFactor");divisor.Value=prior.Field<int>("Divisor");code.ReadOnly=true;kind.Enabled=false;}
        Field("Sabit kural kodu (A–Z, 0–9, _ veya -)",code);Field("Kural adı",name);Field("Tür",kind);Field("Geçerlilik başlangıcı",from);Field("Geçerlilik sonu (açık uç için işareti kaldırın)",to);Field("Birim tutar TL (fazla mesai ekinde kaynak saatlik oran kullanılır)",unit);Field("Yalnız EK fazla mesai katsayısı (örneğin ek %50 için 0,5)",factor);Field("Bölen (aylık için 1–31 değerini açıkça girin)",divisor);Fields.Controls.Add(new Label{AutoSize=true,Text="Günlük ücret tam gün/bir birimdir. Aylık ücret = aylık TL × beyan birimi / açık bölen. Fazla mesai yalnız aktarılmış saatlik temel üzerine EK farktır; yasal katsayı varsayılmaz. Ek ödeme ve doğrudan proje gideri birim × sabit TL kullanır. Kaydet kuralı etkinleştirmez; bağımsız onay gerekir. Yeni sürüm eski mali kayıtları yeniden hesaplamaz."});AcceptTrackedChanges();
    }
    protected override void RefreshEditState(){base.RefreshEditState();if(previous.HasValue)kind.Enabled=false;if(kind.SelectedIndex==0)unit.Enabled=false;else factor.Enabled=false;if(kind.SelectedIndex!=2)divisor.Enabled=false;}
    private void Configure(){bool premium=kind.SelectedIndex==0,monthly=kind.SelectedIndex==2;unit.Enabled=!premium;if(premium)unit.Value=0;factor.Enabled=premium;factor.Value=premium?0:1;divisor.Enabled=monthly;divisor.Value=premium?60:monthly?0:1;}
    protected override object MakeRequest(string reason)=>WageRuleService.ValidatePolicy(new Wire.WagePolicyCreate(project,id,previous,code.Text,name.Text,WageRuleService.Kinds[kind.SelectedIndex],DateTime.SpecifyKind(from.Value.Date,DateTimeKind.Unspecified),to.Checked?DateTime.SpecifyKind(to.Value.Date,DateTimeKind.Unspecified):null,unit.Value,factor.Value,(int)divisor.Value,reason));
}
internal sealed class WageClaimDialog:CalendarEditDialog
{
    private sealed record Target(DataRow Row){public override string ToString()=>Row["AD"]+" "+Row["SOYAD"]+" · "+Row["EmploymentId"];}
    private sealed record Basis(DataRow Row){public override string ToString()=>$"{Row.Field<DateTime>("WorkDate"):dd.MM.yyyy} · {Row["PaidMinutes"]} dk · {Row["HourlyAmount"]} TL/saat · {Row["LineId"]}";}
    private readonly Guid project,policy,claim=Guid.NewGuid();private readonly string kind;
    private readonly ComboBox person=new(){Width=650,DropDownStyle=ComboBoxStyle.DropDownList},basis=new(){Width=650,DropDownStyle=ComboBoxStyle.DropDownList};
    private readonly DateTimePicker from=new(){Width=180,Format=DateTimePickerFormat.Short},to=new(){Width=180,Format=DateTimePickerFormat.Short};private readonly NumericUpDown units=new(){Width=220,Minimum=0,Maximum=1000000,DecimalPlaces=4};private readonly TextBox document=new(){Width=650,MaxLength=100};private readonly CheckBox confirm=new(){AutoSize=false,Width=650,Height=50,Text="Kaynak belgeyi, ücret türünü ve hak birimlerini kontrol ettim; talebi hazırlamayı onaylıyorum."};private readonly Label info=new(){AutoSize=true};private Wire.WageClaimPreview? preview;private Wire.WageClaimScope? prepared;private bool binding;private readonly Button loadBasis=new(){AutoSize=true};
    protected override bool CanSubmit=>preview!=null&&prepared!=null&&confirm.Checked;
    internal WageClaimDialog(Guid project,UserSession user,DataRow rule,DataTable targets):base(user,"Muhasebe — Kuraldan ücret/gider talebi","Ücret/gider talebi")
    {
        this.project=project;policy=rule.Field<Guid>("PolicyId");kind=rule.Field<string>("Kind")!;ClientSize=new(940,900);Fields.Controls.Add(new Label{AutoSize=true,Text=$"{rule["RuleCode"]} · Sürüm {rule["Revision"]} · {rule["Name"]}\nTür: {WagePresentation.Value(kind)}\nBirim TL: {rule["UnitAmount"]} · Ek katsayı: {rule["PremiumFactor"]} · Bölen: {rule["Divisor"]}\nHak birimi otomatik türetilmez; gerekçeli beyan ve bağımsız mali onay gerekir."});
        foreach(DataRow r in targets.Rows)person.Items.Add(new Target(r));Field("Personel / güncel çalışma dönemi (doğrudan giderde kullanılmaz)",person);Field("Hizmet/iş başlangıcı",from);Field("Hizmet/iş bitişi (dahil)",to);Field("Beyan birimi: günlük 1; aylık hak birimi; ek fazla mesai dakika; diğer türlerde miktar",units);Field("Tekrarları önleyen sabit kaynak belge anahtarı",document);
        var load=loadBasis;load.Text="Ek fazla mesai için bu kişi/tarih aralığının aktarılmış saatlik kaynaklarını yükle";Fields.Controls.Add(load);Field("Ek fazla mesai kaynağı (otomatik seçilmez)",basis);person.Enabled=kind!="ProjectExpense";basis.Enabled=load.Enabled=kind=="OvertimePremium";
        var inspect=new Button{Text="Talebi sunucuda önizle / kaynakları kontrol et",AutoSize=true};Fields.Controls.Add(inspect);Fields.Controls.Add(info);Field("Önizleme onayı",confirm);
        foreach(var c in new Control[]{person,from,to,units,document,basis}){if(c is ComboBox combo)combo.SelectedIndexChanged+=(_,_)=>Changed();else if(c is DateTimePicker d)d.ValueChanged+=(_,_)=>Changed();else if(c is NumericUpDown n)n.ValueChanged+=(_,_)=>Changed();else if(c is TextBox t)t.TextChanged+=(_,_)=>Changed();}
        basis.SelectedIndexChanged+=(_,_)=>{if(basis.SelectedItem is not Basis b)return;binding=true;try{from.Value=to.Value=b.Row.Field<DateTime>("WorkDate");}finally{binding=false;}Changed();};
        load.Click+=async(_,_)=>{if(person.SelectedItem is not Target t){MessageBox.Show(this,"Önce çalışma dönemi seçin.");return;}await RunOperationAsync(async ct=>{var data=await new WageRuleService(AppDatabase.ConnectionString,User).BasisAsync(new(project,t.Row.Field<Guid>("EmploymentId"),Date(from),Date(to)),ct);if(IsDisposed)return;binding=true;try{basis.Items.Clear();foreach(DataRow r in data.Rows)basis.Items.Add(new Basis(r));basis.SelectedIndex=-1;}finally{binding=false;}Changed();});};
        inspect.Click+=async(_,_)=>await RunOperationAsync(async ct=>{preview=null;prepared=null;confirm.Checked=false;var request=Scope();var result=await new WageRuleService(AppDatabase.ConnectionString,User).QuoteAsync(request,ct);if(IsDisposed)return;if(System.Text.Json.JsonSerializer.Serialize(Scope())!=System.Text.Json.JsonSerializer.Serialize(request)){info.Text="Önizleme sırasında alan değişti; yeniden önizleyin.";return;}prepared=request;preview=result;confirm.Checked=false;var r=RemoteApi.Decode(result.Detail).Rows[0];info.Text=$"Hesap: {r["Units"]} × {r["UnitAmount"]} × {r["PremiumFactor"]} / {r["Divisor"]} = {r["Amount"]} TL\n"+string.Join("\n\n",result.Notices);});confirm.CheckedChanged+=(_,_)=>RefreshEditState();Fields.SizeChanged+=(_,_)=>{int width=Math.Max(1,Fields.ClientSize.Width-48);person.Width=basis.Width=document.Width=confirm.Width=width;};AcceptTrackedChanges();
    }
    protected override void RefreshEditState(){base.RefreshEditState();if(kind=="ProjectExpense")person.Enabled=false;if(kind!="OvertimePremium")basis.Enabled=loadBasis.Enabled=false;}
    private static DateTime Date(DateTimePicker d)=>DateTime.SpecifyKind(d.Value.Date,DateTimeKind.Unspecified);
    private void Changed(){if(binding)return;preview=null;prepared=null;confirm.Checked=false;info.Text="Seçim/birim değişti; yeni önizleme gerekiyor.";RefreshEditState();}
    private Wire.WageClaimScope Scope(){DataRow? target=(person.SelectedItem as Target)?.Row;if(kind!="ProjectExpense"&&target==null)throw new ArgumentException("Güncel çalışma dönemi seçin.");return new(project,policy,kind=="ProjectExpense"?null:target!.Field<Guid>("EmploymentId"),kind=="ProjectExpense"?null:((byte[])target!["EmploymentVersion"]).ToArray(),Date(from),Date(to),units.Value,kind=="OvertimePremium"?(basis.SelectedItem as Basis)?.Row.Field<Guid>("LineId"):null,document.Text);}
    protected override object MakeRequest(string reason)=>CanSubmit?new Wire.WageClaimCreate(claim,prepared!,preview!.Fingerprint,reason):throw new ArgumentException("Güncel talep önizlemesi ve açık onay gerekiyor.");
}
