internal static class WagePresentation
{
    internal static string Value(string k)=>k switch{"OvertimePremium"=>"Ek fazla mesai farkı","DailyWage"=>"Günlük temel ücret","MonthlyWage"=>"Aylık temel ücret","ExtraPay"=>"Ek ödeme / prim","ProjectExpense"=>"Doğrudan proje gideri","Approve"=>"Onay","Reject"=>"Ret","Cancel"=>"İptal","RequestReverse"=>"Tam ters aktarım isteği","ApproveReverse"=>"Bağımsız ters aktarım onayı","Post"=>"Deftere aktarım","Reverse"=>"Tam ters aktarım","Prepared"=>"Hazırlanmış","Approved"=>"Bağımsız onaylı","Posted"=>"Aktarılmış","Rejected"=>"Reddedilmiş","Cancelled"=>"İptal edilmiş","ReverseRequested"=>"Ters aktarım isteği var","ReverseApproved"=>"Ters aktarım onaylı","Reversed"=>"Tam ters aktarılmış",_=>k};
    private static readonly Dictionary<string,string> Titles=new(){["RuleCode"]="Kural kodu",["Revision"]="Sürüm",["Name"]="Kural adı",["Kind"]="Tür / işlem",["ValidFrom"]="Geçerlilik başlangıcı",["ValidTo"]="Geçerlilik sonu",["UnitAmount"]="Birim TL",["PremiumFactor"]="Ek katsayı",["Divisor"]="Bölen",["DecisionKind"]="Kural kararı",["DecidedBy"]="Karar veren",["DecidedUtc"]="Karar UTC",["FromDay"]="Hizmet başlangıcı",["ToDay"]="Hizmet bitişi",["DocumentKey"]="Kaynak belge anahtarı",["Units"]="Beyan birimi",["Amount"]="Mali tutar TL",["WorkflowState"]="Talep durumu",["CreatedBy"]="Hazırlayan",["CreatedUtc"]="Kayıt UTC",["Reason"]="Gerekçe",["CanDecide"]="Bağımsız karar verilebilir",["PersonCaption"]="Kayıttaki kişi",["Actor"]="İşlemi yapan",["BeforeBalance"]="Önceki bakiye TL",["AfterBalance"]="Sonraki bakiye TL"};
    internal static void Format(DataGridView grid){grid.DataBindingComplete+=(_,_)=>{foreach(DataGridViewColumn c in grid.Columns){c.HeaderText=Titles.GetValueOrDefault(c.Name,c.HeaderText);if(c.Name=="PremiumFactor"||c.Name=="Units")c.DefaultCellStyle.Format="N4";}};grid.CellFormatting+=(_,e)=>{if(e.ColumnIndex>=0&&grid.Columns[e.ColumnIndex].Name is "Kind" or "DecisionKind" or "WorkflowState"&&e.Value is string s){e.Value=Value(s);e.FormattingApplied=true;}};}
}
